SELECT analytics_expense_facts.expense_category, SUM(analytics_expense_facts.expense_amount) AS expense_amount FROM analytics_expense_facts WHERE analytics_expense_facts.year = 2022 AND analytics_expense_facts.month = 8 AND analytics_expense_facts.department = 'department_06' AND analytics_expense_facts.cost_center = 'cc_036' GROUP BY analytics_expense_facts.expense_category ORDER BY expense_amount DESC, analytics_expense_facts.expense_category ASC LIMIT 15
